properties.query:
let QuietThreshold = 2h;
// One row is always returned; LastIngested is null when nothing arrived within the query period.
CSEEvents_CL
| summarize LastIngested = max(ingestion_time()), LastEventTime = max(TimeGenerated)
| where isnull(LastIngested) or LastIngested < ago(QuietThreshold)
| extend HoursSinceLastIngestion = iff(isnull(LastIngested), real(null), round((now() - LastIngested) / 1h, 1))
